115	            OrbLabel(state: session.orb, label: orbLabel)
116	        }
117	        .padding(.bottom, 8)
118	        .frame(maxWidth: .infinity)
119	        .animation(.timingCurve(0.4, 0, 0.2, 1, duration: Theme.Motion.base), value: session.orb)
120	    }
121	
122	    private var orbLabel: String? {
123	        if session.orb == .idle { return "Ready" }
124	        return session.label
125	    }
126	}
