156	/// What the mascot says (`reply.say`), plus the turn's tool steps as one quiet line.
157	struct MascotBubble: View {
158	    let say: String
159	    let steps: [String]
160	
161	    @Environment(\.typeScale) private var type
162	
163	    var body: some View {
164	        VStack(alignment: .leading, spacing: 12) {
165	            if !steps.isEmpty {
166	                Label {
167	                    Text(steps.map(Self.pastTense).joined(separator: " · "))
168	                        .eyebrow(type)
169	                } icon: {
170	                    Image(systemName: "checkmark.circle.fill")
171	                        .foregroundStyle(Theme.accentText)
172	                }
173	                .font(type.eyebrow)
174	                .lineLimit(1)
175	            }
176	            Text(say)
177	                .font(type.answer)
178	                .tracking(type.answerTracking)
179	                .foregroundStyle(Theme.textPrimary)
180	                .fixedSize(horizontal: false, vertical: true)
181	        }
182	        .padding(20)
183	        .frame(maxWidth: .infinity, alignment: .leading)
184	        .glassSurface(.panel, cornerRadius: Theme.Radius.xxl)
185	        .accessibilityElement(children: .combine)
186	    }
187	
188	    /// "Checking trains…" → "Checked trains".
189	    static func pastTense(_ label: String) -> String {
190	        var text = label.trimmingCharacters(in: CharacterSet(charactersIn: "…. "))
191	        if let first = text.split(separator: " ").first, first.hasSuffix("ing") {
192	            let stem = first.dropLast(3)
193	            let past = stem.hasSuffix("e") ? stem + "d" : stem + "ed"
194	            text = String(past) + text.dropFirst(first.count)
195	        }
196	        return text
197	    }
198	}
